def is_palindrome(s):
    """判断字符串 s 是否为回文"""
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

# 如果输入是整数，可先转为字符串再判断：
def is_palindrome_num(n):
    """判断整数 n 是否为回文数"""
    if n < 0:
        return False
    s = str(n)
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return False
